def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: An integer representing the number of nanoseconds since the Unix epoch.
    :param tz: An optional string representing the timezone in the format 'UTC' or '+HH:MM' or '-HH:MM'.
    :return: A `time` object representing the given nanoseconds.
    """
    try:
        import datetime
        if not isinstance(nanoseconds, int):
            raise ValueError("nanoseconds must be an integer")
        if tz:
            if not isinstance(tz, str):
                raise ValueError("tz must be a string")
            if tz != 'UTC' and (len(tz) != 6 or tz[0] not in ('+', '-') or not tz[1:3].isdigit() or not tz[4:].isdigit()):
                raise ValueError("tz must be 'UTC' or '+HH:MM' or '-HH:MM'")
        dt = datetime.datetime.utcfromtimestamp(nanoseconds / 1e9)
        if tz == 'UTC':
            return dt.timetz()
        elif tz:
            offset = int(tz[1:3]) * 3600 + int(tz[4:]) * 60
            if tz[0] == '-':
                offset = -offset
            return dt.astimezone(datetime.timezone(datetime.timedelta(seconds=offset))).timetz()
        else:
            return dt.time()
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

