    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds parameter must be an integer")

    if tz is not None and not isinstance(tz, timezone):
        raise ValueError("tz parameter must be a timezone object or None")

    hours, remainder = divmod(nanoseconds, 3600000000000)
    minutes, remainder = divmod(remainder, 60000000000)
    seconds, nanoseconds = divmod(remainder, 100000000)

    if tz is not None:
        dt = datetime(1970, 1, 1, hour=hours, minute=minutes, second=seconds, microsecond=nanoseconds // 1000, tzinfo=tz)
        return dt.time()
    else:
        dt = datetime.utcfromtimestamp(nanoseconds // 1000000000)
        return dt.time()

