        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        def format_stack(stack, level, path):
            if level >= max_level or path >= max_path_level:
                return
            for filename, line_no, func_name, source in stack:
                if line_no is not None:
                    yield f"{filename}:{line_no} {func_name}()"
                if source is not None:
                    yield f"  {source}"

        def format_exception_recursive(exc, level, path):
            if level >= max_level:
                return f"... {type(exc).__name__}: {exc}"
            try:
                s = str(exc)
            except Exception as sub_exc:
                s = format_exception_recursive(sub_exc, level + 1, path)
            stack = traceback.extract_tb(exc.__traceback__)
            formatted_stack = "\n".join(format_stack(stack, level, path))
            return f"{type(exc).__name__}: {s}\n{formatted_stack}"

        import traceback
        return format_exception_recursive(e, 0, 0)

