                with zip_ref.open(xml_file) as xml_data:
                    package_name, data = get_package_data(xml_data)
                    file_groups.setdefault(package_name, []).append((xml_file, data))

            return file_groups

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

