def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    def clean_string(s):
        s = s.upper().strip()
        s = s.replace('-', '')
        s = s.replace('.', '')
        return s

    number = None
    suppl = False

    issue = issue.strip()
    if issue.startswith('issue'):
        issue = issue[len('issue'):].strip()

    if 'SPE' in issue.upper():
        suppl = True

    if issue.isdigit() and int(issue) > 0:
        number = int(issue)

    if number is not None:
        mod = issue.replace(str(number), '').strip()
        if 'SUPPL' in mod.upper():
            suppl = True
            if mod == 'SUPPL':
                suppl = 1
            elif mod == 'SUPPL 1':
                suppl = 1
            elif mod.find('1') != -1:
                suppl = 1
            elif mod.find('-') != -1:
                parts = mod.split('-')
                if len(parts) == 2:
                    begin, end = parts
                    begin = begin.strip()
                    end = end.strip()
                    if begin.isdigit() and end.isdigit():
                        suppl = int(end)
                    elif begin.isdigit():
                        suppl = int(begin)
            elif mod.find('.') != -1:
                parts = mod.split('.')
                if len(parts) == 2:
                    begin, end = parts
                    begin = begin.strip()
                    end = end.strip()
                    if begin.isdigit() and end.isdigit():
                        suppl = int(end)

    return number, suppl

