def get_repo_archive(url: str, destination_path: Path) -> Path:
    if not Path(url).suffix == ".tar.gz":
        raise ValueError("Invalid URL: The provided URL does not point to a .tar.gz file.")

    if not destination_path.exists():
        raise FileNotFoundError(f"Invalid destination path: {destination_path.resolve()} does not exist.")
    if not destination_path.is_dir():
        raise NotADirectoryError(f"Invalid destination path: {destination_path.resolve()} is not a directory.")
    if not destination_path.writable():
        raise PermissionError(f"Invalid destination path: {destination_path.resolve()} is not writable.")

    response = requests.get(url, stream=True)
    if response.status_code != 200:
        raise Exception(f"Failed to download archive: Received status code {response.status_code}.")

    with open(destination_path / PurePath(url).name, 'wb') as file:
        for chunk in response.iter_content(chunk_size=8192):
            file.write(chunk)

    with tarfile.open(destination_path / PurePath(url).name, 'r:gz') as tar:
        tar.extractall(path=destination_path)

    return destination_path

