    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    try:
        name, default = matcher.split('=', 1)
        value = os.getenv(name.strip())
        if value is None:
            if default:
                return default.strip()
            else:
                raise KeyError(f"Environment variable '{name.strip()}' not set and no default value provided.")
