def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    for node in graph.subjects(prop):
        if not graph.subjects(prop, node):
            roots.add(node)

    return roots

def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()
    else:
        roots = set(roots)

    nodes = set(graph.subjects(prop))

    while nodes:
        new_nodes = set()
        for node in nodes:
            parents = set(graph.objects(node, prop))
            if not roots.intersection(parents):
                new_nodes.add(node)
        roots.update(new_nodes)
        nodes = new_nodes

    return roots

