    bin_centers = (bin_edges[:-1] + bin_edges[1:]) / 2
    values = hist.values

    if scale is None:
        graph_scale = None
    elif scale is True:
        graph_scale = hist.scale
    else:
        raise ValueError("Invalid scale value. Must be None or True.")

    graph_points = []
    for i, bin_value in enumerate(values.flat):
        value_tuple = make_value(bin_value)
        if get_coordinate == "left":
            x_value = bin_edges[i]
        elif get_coordinate == "right":
            x_value = bin_edges[i + 1]
        else:  # get_coordinate == "middle"
            x_value = bin_centers[i]
        point = tuple([x_value] + list(value_tuple))
        graph_points.append(point)

    return np.array(graph_points, dtype=[(name, np.float64) for name in field_names])

