def list_of_file_names(settings_dirs, spec_option):
    """
    Generate a list of file names from the specified settings directories.

    Args:
    settings_dirs (list): A list of directory paths.
    spec_option (str): A specific option for filtering files.

    Returns:
    list: A list of file names that match the specified option.

    Raises:
    ValueError: If settings_dirs is not a list or if spec_option is not a string.
    FileNotFoundError: If any directory in settings_dirs does not exist.
    """
    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    file_names = []
    for dir_path in settings_dirs:
        if not os.path.exists(dir_path):
            raise FileNotFoundError(f"Directory {dir_path} does not exist")
        for root, dirs, files in os.walk(dir_path):
            for file in files:
                if spec_option in file:
                    file_names.append(os.path.join(root, file))
    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """
