    Args:
    settings_dirs (list of str): A list of directories containing the settings files.
    spec_option (str): A specification option to filter the files (e.g., 'all', 'config', 'log').

    Returns:
    list of str: A list of file names that match the specified option.

    Raises:
    ValueError: If spec_option is not one of the expected values.
    FileNotFoundError: If any of the settings directories do not exist.
    """
    valid_options = {'all', 'config', 'log'}

    if spec_option not in valid_options:
        raise ValueError(f"Invalid spec_option: {spec_option}. Expected one of {valid_options}")

    file_names = []

    for settings_dir in settings_dirs:
        if not os.path.isdir(settings_dir):
            raise FileNotFoundError(f"Directory {settings_dir} does not exist")

        for root, _, files in os.walk(settings_dir):
            for file in files:
                if spec_option == 'all' or (spec_option == 'config' and file.endswith('.conf')) or (spec_option == 'log' and file.endswith('.log')):
                    file_names.append(os.path.join(root, file))

    return file_names

