    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise ValueError("The yaml_file parameter is required")

    if not os.path.exists(yaml_file):
        raise FileNotFoundError(f"The file {yaml_file} does not exist")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)
            if not data:
                raise ValueError(f"The file {yaml_file} is empty")

            # Example of mandatory fields validation
            mandatory_fields = ['field1', 'field2']
            for field in mandatory_fields:
                if field not in data:
                    raise IRValidatorException(f"Mandatory field '{field}' is missing in file {yaml_file}")

            return data

    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}")
    except Exception as e:
        raise IRValidatorException(f"An error occurred while validating the YAML file: {e}")

