def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Invalid plugin directory: {plugin_dir}")

    plugin_spec_path = os.path.join(plugin_dir, 'plugin.spec')
    if not os.path.isfile(plugin_spec_path):
        raise FileNotFoundError(f"Plugin spec file not found: {plugin_spec_path}")

    config = ConfigParser()
    try:
        config.read(plugin_spec_path)
    except Exception as e:
        raise ValueError(f"Error reading plugin spec file: {e}")

    flatten_dict = {}
    for section in config.sections():
        for key, value in config.items(section):
            flatten_dict[f"{section}.{key}"] = value

    return flatten_dict

